<script setup lang="ts">
import TableSortHeader from '@/components/TableSortHeader.vue'
import TablePager from '@/components/TablePager.vue'
import {useClientTable} from '@/features/table/useClientTable'
import {useColumnWidths} from '@/features/table/useColumnWidths'
import {useDebouncedValue} from '@/features/table/useTableView'

import {onMounted,ref,computed} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {listAdminApprovals,approveAdminOperation,rejectAdminOperation} from '@/api/admin'
import {getResourceTree} from '@/api/resource'
import {errorMessage} from '@/api/asset-ops'
import type {ApprovalRecord} from '@/types/device'
import '@/styles/asset-ops.css'
const racks=ref<Record<string,string>>({})
const rows=ref<ApprovalRecord[]>([]),status=ref('PENDING'),loading=ref(false),deciding=ref('')
const operationLabels:Record<string,string>={ASSIGN:'上架',MOVE:'迁移',DECOMMISSION:'下架'}
const statusLabels:Record<string,string>={PENDING:'待审批',APPROVED:'已批准',REJECTED:'已驳回',CANCELLED:'已取消'}
let loadRequest=0
const loadFailed=ref(false)
async function load(){const request=++loadRequest;page.value=1;loading.value=true;loadFailed.value=false;try{const next=await listAdminApprovals(status.value||undefined);if(request!==loadRequest)return;rows.value=next.items}catch(e){if(request===loadRequest){loadFailed.value=true;ElMessage.error(errorMessage(e))}}finally{if(request===loadRequest)loading.value=false}}
function position(row:ApprovalRecord){const p=row.operation==='DECOMMISSION'?row.sourcePosition:null;const rack=p?.rackId||row.targetRackId;const start=p?.startU||row.targetStartU;const height=p?.heightU||row.targetHeightU;return (racks.value[rack]||rack)+' · '+start+'-'+(start+height-1)+'U'}
async function decide(row:ApprovalRecord,approve:boolean){
  if(deciding.value)return
  let comment:string
  try{const r=await ElMessageBox.prompt(approve?(row.operation==='DECOMMISSION'?'批准后将释放原 U 位；设备或原位置变化会阻止执行。':'批准时重新校验设备版本和目标 U 位。'):'确认驳回该申请？设备位置保持不变。',approve?'批准申请':'驳回申请',{inputPlaceholder:'审批意见（可选）'});comment=r.value}catch{return}
  deciding.value=row.id
  try{if(approve)await approveAdminOperation(row.id,row.version,comment);else await rejectAdminOperation(row.id,row.version,comment);ElMessage.success(approve?'审批已通过并执行':'申请已驳回');await load()}catch(e){ElMessage.error(errorMessage(e))}finally{deciding.value=''}
}
const search=ref(''),query=useDebouncedValue(search)
const filteredRows=computed(()=>rows.value.filter(row=>!query.value.trim()||[row.device?.name,row.device?.code,row.deviceId,row.reason,row.decisionComment,position(row)].some(value=>String(value||'').toLowerCase().includes(query.value.trim().toLowerCase()))))
const {page,pageSize,total,pageRows,tableRef,sortBy,onSortChange}=useClientTable(filteredRows,{deviceName:row=>row.device?.name||row.deviceId,operationLabel:row=>operationLabels[row.operation]||row.operation,position:row=>position(row),statusLabel:row=>statusLabels[row.status]||row.status})
function clearSearch(){search.value='';query.value=''}
onMounted(async()=>{await Promise.all([load(),(async()=>{try{const tree=await getResourceTree();for(const dc of tree.items||[])for(const room of dc.rooms||[])for(const rack of room.racks||[])racks.value[rack.id]=dc.name+' / '+room.name+' / '+rack.name}catch{}})()])})
const {columnWidths:columnWidths,resizeColumn:resizeColumn}=useColumnWidths({"deviceName": 180, "operationLabel": 110, "position": 220, "reason": 160, "statusLabel": 110, "requestedAt": 175, "decisionComment": 150})
</script>
<template><div class="asset-ops"><div class="ops-heading"><div><h1>审批中心</h1><p>集中处理上架、迁移和下架申请，审批规则及通知渠道在系统管理中维护。</p></div></div><el-card shadow="never"><div class="ops-toolbar between"><el-select v-model="status" style="width:160px" @change="load"><el-option label="全部状态" value=""/><el-option v-for="(label,key) in statusLabels" :key="key" :label="label" :value="key"/></el-select><el-button :loading="loading" @click="load">刷新</el-button></div><el-input v-model="search" clearable aria-label="搜索审批记录" placeholder="搜索设备、位置、原因或审批意见" style="max-width:420px;margin-bottom:12px"/><el-alert v-if="loadFailed" title="加载失败，当前行可能不是最新审批记录，请刷新重试" type="error" :closable="false"/><el-table :data="pageRows" :aria-busy="loading||search!==query" ref="tableRef" @sort-change="onSortChange" v-loading="loading"><el-table-column label="设备 / 编码" prop="deviceName" sortable="custom" :width="columnWidths['deviceName']"><template #header><TableSortHeader label="设备 / 编码" :width="columnWidths['deviceName']" @sort="sortBy('deviceName')" @resize="resizeColumn('deviceName',$event)"/></template><template #default="{row}">{{row.device?.name||row.deviceId}}<small class="ops-block ops-muted">{{row.device?.code}}</small></template></el-table-column><el-table-column label="操作" prop="operationLabel" sortable="custom" :width="columnWidths['operationLabel']"><template #header><TableSortHeader label="操作" :width="columnWidths['operationLabel']" @sort="sortBy('operationLabel')" @resize="resizeColumn('operationLabel',$event)"/></template><template #default="{row}"><el-tag :type="row.operation==='DECOMMISSION'?'warning':'info'">{{operationLabels[row.operation]||row.operation}}</el-tag></template></el-table-column><el-table-column label="位置（下架显示原位置）" prop="position" sortable="custom" :width="columnWidths['position']"><template #header><TableSortHeader label="位置（下架显示原位置）" :width="columnWidths['position']" @sort="sortBy('position')" @resize="resizeColumn('position',$event)"/></template><template #default="{row}">{{position(row)}}</template></el-table-column><el-table-column label="申请原因" prop="reason" sortable="custom" :width="columnWidths['reason']"><template #header><TableSortHeader label="申请原因" :width="columnWidths['reason']" @sort="sortBy('reason')" @resize="resizeColumn('reason',$event)"/></template></el-table-column><el-table-column label="状态" prop="statusLabel" sortable="custom" :width="columnWidths['statusLabel']"><template #header><TableSortHeader label="状态" :width="columnWidths['statusLabel']" @sort="sortBy('statusLabel')" @resize="resizeColumn('statusLabel',$event)"/></template><template #default="{row}"><el-tag :type="row.status==='APPROVED'?'success':row.status==='REJECTED'?'danger':'info'">{{statusLabels[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="申请时间" prop="requestedAt" sortable="custom" :width="columnWidths['requestedAt']"><template #header><TableSortHeader label="申请时间" :width="columnWidths['requestedAt']" @sort="sortBy('requestedAt')" @resize="resizeColumn('requestedAt',$event)"/></template><template #default="{row}">{{new Date(row.requestedAt).toLocaleString('zh-CN')}}</template></el-table-column><el-table-column label="审批意见" prop="decisionComment" sortable="custom" :width="columnWidths['decisionComment']"><template #header><TableSortHeader label="审批意见" :width="columnWidths['decisionComment']" @sort="sortBy('decisionComment')" @resize="resizeColumn('decisionComment',$event)"/></template></el-table-column><el-table-column label="处理" width="140" fixed="right"><template #default="{row}"><template v-if="row.status==='PENDING'"><el-button link type="success" :disabled="!!deciding||loading||loadFailed" @click="decide(row,true)">通过</el-button><el-button link type="danger" :disabled="!!deciding||loading||loadFailed" @click="decide(row,false)">驳回</el-button></template><span v-else class="ops-muted">已处理</span></template></el-table-column><template #empty><el-empty :description="query?'没有匹配审批记录':'暂无审批记录'"><el-button v-if="query" @click="clearSearch">清除筛选</el-button></el-empty></template></el-table><TablePager v-model:page="page" v-model:page-size="pageSize" :total="total" label="审批记录"/></el-card></div></template>
